namespace OpenTPW.UI.Original;

/// <summary>
/// Register of every UI value or rule that is not taken from original data or hard evidence
/// (docs/UI.md "Approximation register"). Each site carries a matching
/// <c>// [APPROX:UI-NNN]</c> comment; <see cref="LogOnce"/> reports them at startup.
/// </summary>
public static class UiApproximations
{
	public static readonly IReadOnlyList<(string Id, string Assumption, string EvidenceNeeded)> All = new[]
	{
		("UI-003", "button/arm state frames drawn at the root node pose; child translations ignored; the control's model setter 0x65d070 (model at +0x98, model vtable +0xc with 0x57, then +0x14) is found, the node walk that submits the triangles is not", "the node walk of the PC UI model draw (the selected state mesh -> local matrix -> ancestor composition), or a capture of a button whose state child is offset"),
		("UI-004", "UI model triangles drawn back to front by Z, grouped per texture; the original's display object divides its depth buffer into a UI range in front of a linear and a log range (the dump 0x5833c0 prints [+0x48] begin, [+0x4c] ui end / linear begin, [+0x50] linear end / log begin, [+0x54] log end; the buffer itself is enabled or not, strings 0x768988 and 0x768958), which suggests depth-tested rather than sorted UI parts, not shown for the UI model draw; the device init 0x573080 sets ZENABLE 1, ZFUNC LESSEQUAL (4) and ZWRITEENABLE 1 when the display object's flag +0x88 bit 0x10 is set and ZENABLE and ZWRITEENABLE 0 otherwise, so a UI part is depth-tested when the buffer is on, but the UI draw's own state and order are not found", "the UI model draw call (which per-draw depth state and which order it submits) and the writer of the four range floats +0x48..+0x54"),
		("UI-006", "text colours: window titles and the lobby island name yellow, the object windows' labels and values white, the pause menu's lines cyan (white while focused), green values elsewhere, grey disabled, shadow and backdrop colours (the video's 720p chroma is good to about +-15 per channel); the original gives each text control an RGBA colour (0x65c5d5 → renderer +0x48, kept as ARGB at +0x78, 0x48fd07; the sprite draw 0x58a010 takes it as the diffuse colour of the control's quads, 0x58a019) and renders its glyphs white (0x48fa96) unless the control keeps the font's own colours (+0xdd); the values traced are the options labels' (0,0,0,255) (0x4a441e, UI-037), the buy list rows' (255,255,255,255) (0x4ad340), the pause menu lines' (0,175,190,255) (0x48b2b9) and the shared title colour (234,239,102,255) (0x492d20, fifteen window builders), with the lobby island name's second line (252,232,7,255) (0x4b8604) and a list row control that turns (140,0,60) on message 0x403 with a negative argument (0x4a0710); the other 0x65c5d5 calls (134 sites in all; by an instruction scan: about 36 with white (255,255,255,255), 31 with black (0,0,0,255) such as the runs 0x49ada6-0x49b385 and 0x4a53a2-0x4a5d26, 7 with red (255,0,0,255) at 0x49ff69, 0x4a002f, 0x4a6273 and 0x4b2e93-0x4b31f7, 5 with (224,86,86,255) at 0x4aa82d-0x4aac70, and about 45 that pass the colour from registers or tables) are not yet assigned to screens", "which screen each remaining 0x65c5d5 call colours (values, disabled states, costs) and the backdrop colours"),
		("UI-007", "one-pixel (×UI scale) drop shadow under UI text; the original's control text renderer (0x48f830) lays each string out and draws it once (one 0x6ae0f0 call into the control's bitmap), so its controls have no drop shadow; the whole glyph layout and draw library has one draw entry, 0x6ae0f0, whose only caller is the text box routine 0x492750 (three callers, each calling it once: the label and list text of 0x4a84c0 through 0x492c40, 0x480810 through 0x47fcd0 and 0x480460, 0x480570 through 0x47fe90; 0x6ae1c0 is the measure entry used by 0x4929f0), no offset or second pass exists there, and the BF4 glyphs carry only 0-15 coverage samples (docs/BF4-FONTS.md), so no shadow is baked into the font art; the control's attribute byte +0xdb is only ever written (the constructors 0x48f703, 0x48fe3d, 0x490091 and the attribute setter 0x48fcab; no read form of it exists in tp.exe's code by a byte scan), so it is no shadow flag; the capture's apparent shadow is not explained, and the vtable-reached control renderer 0x48f830 and the sprite blit of its bitmap (0x48f410) are not shown to add one; the control draws into its own bitmap in the display mode's pixel format (0x4925d0 copies the 32-byte mode record at 0x8bd558, bit depth and channel masks, into the surface description; 0x48fb64 clears the bitmap to zero first), through the blended one-colour glyph blitters: the 5-5-5 one (0x6b0760) blends each channel as dst + ((src - dst) * coverage) / 15 in signed 5-bit arithmetic and keeps the destination's alpha bit, so white text on the cleared bitmap yields grey levels with alpha bit 0 and the coverage reaches the screen only through the sprite draw's state; the 32-bit blitter 0x6b15f0 (slot 1 of its class; the classes are the vtables from 0x70a18c on) blends each channel the same way and keeps the destination's alpha byte (0xff000000), so the text bitmap never carries coverage in its alpha; the texture format index [0x8bd554] (32-byte records at 0x8bd558 filled by the format enumeration 0x572f70 from the table 0x7015f8: 0 = 5-6-5, 1 = 1-5-5-5, 2 = 4-4-4-4, 3 = 8-8-8-8) is 2 or 3 by option bit 0x400000 of [0x7a1a8c] (0x44e1eb-0x44e21f, 0x58da40; always 3 when [0x8bd524] is 4), so the 5-5-5 blitter read above is not the one a default run uses; the text control is a sprite object: its sprite record at control +0x54 (built by 0x588d70) has the colour at record +0x24 (control +0x78, default 0xffffffff), the flags at +0x10 (control +0x64, 0x30000) and the scale at +0x2c (control +0x80, 1.0), and its bitmap (control +0x9c) is split into texture pages by 0x5889b0; the sprite draw that submits such records is 0x58a010 (a grid of pre-transformed quads, FVF 0x1c4, one diffuse colour per quad read from record +0x24 at 0x58a019, state word 0x400 = alpha test enabled, plus the fog bit 0x100000 of the page flags, through 0x565f90 and the state applier 0x567620), so the control colour is the quad's diffuse colour and no second pass or offset exists there either", "the blend and texture-stage state the text quads are drawn with (what the state words and page flags 0x5180200 select through the setters 0x567a70 and 0x567620: alpha reference table 0x7012d8, blend factors, colour and alpha operation) and the 4444 and 8888 blitters' alpha handling, to tell how grey coverage with alpha 0 becomes the capture's soft edges and whether the capture's apparent shadow is a render-state effect (UI-037)"),
		("UI-008", "text buttons on purple_button art (a texture name of the Mac build: tp.exe holds no 'purple' string, so which art the PC front-end buttons use is unread): each half is one end cap, drawn with its mirror image; upper half normal, lower half focused/pressed", "the PC front-end button drawer and its art names (not found by string; look for the models the front-end tables name), or a capture of the original front-end buttons"),
		("UI-013", "the confirm dialog follows table 0x7583e8, the game-mode screen the name dialog 0x753f50 and the load screen the load dialog 0x7523f0, whose rows show the park's name and, right-aligned, the save file's local date and time as 0x49ec80 formats them (UITEXT 0x1c0 with day, month and year, then \" %02d:%02d\"; shipped parks and the sandbox have no file time and show none); the lobby's and the park's pause menus lay out their lines as 0x48c150 → 0x492f60 does (text width + 1 and height + 5 pixels on the canvas, centred, from top 10, 5 units apart), but the height follows OpenTPW's menu font tier ([EXT:ui-font-tier-by-scale]) the park pause menu's online variant is read (0x48c36c-0x48c4af: top and gap are 5 each, or 0 when the net-session object's field +0x60, read by 0x5b6450, is non-zero; the field is cleared at creation (0x5b51a7) and by the error codes 0x4b, 0x4c, 0x4d, 0x4e and 0x37 (0x5b6375-0x5b63dd) and set to 1 by a received reply (0x5b6363)), so an offline park keeps OpenTPW's top 10 and gap 5 and the 0 variant needs the online reply state; the measure 0x4929f0 is read and matched (it lays the text out in a box through 0x6ae1c0 and returns the block box, the widest line by lines times line height, which is OpenTPW's text layout box; with its wrap flag clear the box is 0x4000 wide, so nothing wraps); the focused line's hover ramp is built (0x48b2a0 sets the ramp slot to +1 on message 0x10001 and -1 on 0x10002, 0x48b220 steps it on every message 0x1e, eight frames at the 60 Hz reference, [EXT:frame-driven-at-60hz], from grey 0x21 in steps of 0x20 to white; the ramp is driven by OpenTPW's focus, [EXT:pause-menu-hover-focus])", "which online replies set the net-session field +0x60 (the callers of 0x5b6290-0x5b6340) and OpenTPW's equivalent, for the zero top and gap; OpenTPW's menu font tier"),
		("UI-018", "the lobby backdrop is painted flat with the cloud layer's eased colour (red toward the blue target) as a stand-in: the original clears to the fog colour 0x44DDFF and tints only its cloud layer (the engine sky's sky.tga, coloured from that grid), which is not drawn, nor is the scene's fog; two settings gate the eased colour and the flying-mesh count share, all in the .bss settings block 0x785840-0x785920 filled at runtime ([0x785888] > 1 and the options word 0x78d8d8 == 1 assumed to pass, as the capture's tinted clouds show; [0x7858dc] assumed 100 %, the video's flocks cannot be counted at 720p); an island without SKYCOLOUR gets black instead of the random target its constructor draws (0x5dfb4a-0x5dfb7b, three CRT rand() calls per island); the island clips are picked by a local stand-in for the C runtime's rand(); while the globe is up the lobby's flyers and island clips hold still (the original's per-frame lobby update 0x5d5c50 has no globe branch and the main state stays 2, 0x54e6c7, while GLOBERADIUSIN and GLOBERADIUSOUT are lobby-file commands, so the original probably keeps stepping them behind the globe; whether the lobby scene is drawn then is not traced); the enter sequence is built (the camera turns to the island angle + π, the gate plays M1, the camera zooms under the black fade and the park starts below radius 8, 0x5e0490 states 1 and 2; an early leave's gate M2 close, 0x5e1350, is not reachable from the front end here); the key-unlock sequence is not traced; the lightning flash is not drawn (the capture shows none)", "the engine sky's draw (0x585ee0-0x586a00) and fog, the runtime contents of the settings block 0x785840-0x785920 and the options word 0x78d8d8, the lobby's subsystems while the globe is up, the key-award animation's code"),
		("UI-024", "the object windows (tables 0x755150, 0x755908, 0x755e80) draw their controls at the table rectangles and, for a shop or sideshow, the customer satisfaction gauge from the object's visit history (0x4e1e30), but the preview is OpenTPW's orthographic icon ([EXT:preview-icon-cpu-projection]); the local happiness gauge counts the guests on park cells at the object's anchor cell where 0x4cd880 walks the thing lists of the cells around the thing's own cell; the build window fits the preview size to translated names and prices", "the thing cell byte pair (+5, +7) an object keeps and whether it is the placement anchor"),
		("UI-025", "the message tube holds up to five messages (the most the video shows) and drops the oldest on overflow, where the original's tube has eight 24-byte slots (insert 0x59a940; a message is admitted by 0x59abc0 under a per-type cap, 0x59c320, from the registry 0x76e300) and, with every slot full, replaces the lowest-priority slot only when that priority is lower than its own and is otherwise dropped; pending messages are not saved with the park, as in the original (its MESS chunk, 0x40fc80, holds only the 29 category id sets); the panel's rectangles are table 0x7501a0; its action buttons take the mb_ model of their kind (the original's table 0x48e610: kinds 3 and 4 mb_locate, 9 to 0x11 mb_buy, 0x12 b_loan, 0x13 mb_resrch, 0x14 b_pkinfo, 0x15 b_staffcost, 0x17 mb_callmech, 0x18 b_entry, 0x1a mb_accept, 0x1b mb_decline), but only the challenge offers carry actions (Accept and Decline) here and the other kinds' events are not ported; the strike messages (TAG_SYSTEM.str) and the challenge offers use the tube; its red body and white icons are OpenTPW's art ([EXT:message-tube-art]), an unanswered offer that was deleted is posted again ([EXT:challenge-offer-repost]) and OpenTPW's own feedback lines stay in a status line ([EXT:status-line])", "the registry's per-type caps and priorities (filled at run time, the loader 0x50af78 is not traced) and whether the tube draws eight icons"),
		("UI-026", "build icons: the preview model (P<name>.MD2, else the main model) is drawn by OpenTPW's CPU projection ([EXT:preview-icon-cpu-projection]); the buy window takes the original's 45° tilt (0x468e50), its turn of 0.0004 rad a millisecond that runs on across selections (0x46908a, 0x468e2f) and its fit (0x4689f0), but the original draws the preview through its 3D object pipeline (the ride object made by 0x463060 with a world matrix that 0x468e50 rebuilds each frame: the yaw and the ±π/4 tilt through the sine table, the matrix's x column scaled by 0.75 and its depth column by 0.1, then offsets) and starts the model's animation 5 (0x4732a0), which OpenTPW does not; the selected item's footprint grid (8×8 cells coloured by cell type in control 0x1eb, 0x4ab1b0, record 0x754d50) is built (BuyFootprint), with the 1-pixel edges of its cell rectangles not traced; the object windows' previews keep a 30° tilt and 0.8 rad/s; sign faces use the object's rendered sign textures (ObjectSigns)", "the camera and projection the 3D pipeline draws the preview object with, the offset terms of 0x468e50 and the meaning of animation 5"),
		("UI-027", "a park click selects the object occupying the cell of the cursor's terrain hit (TerrainRayPick: 0x45bf90's heightfield triangles, the cell 0x45d560); the original selects a ride, shop or other object by its pick sprite: the sprite pass 0x5890e0 picks the nearest sprite flagged 0x200 under the cursor (a circle round its projected anchor), 0x532bd0 finds its owner among the things of the 3 x 3 cells round the hovered cell (types 1, 4 to 8 and 0x12), the hover handler 0x486d90 turns a hovered type 5, 4, 6, 7 or 8 into cursor mode 8, 9, 0xa, 0xb or 0xc and the click dispatcher 0x4879d0 opens the object window 0x4b6080 for it, only outside the visitor pick state (Shift alone or the visitor locator panel out); the ray's object hit [0x7a1cd4] selects nothing: its only readers copy it to the camera control block 0x79c6ac (0x443aab, 0x443d23)", "which model instances carry a pickable sprite (flag 0x200; the instance word +0x114 that 0x475ef0 tests: it maps a sprite at instance +0xd0 to its instance, +0x114 is copied by 0x475eb0 and cleared at 0x4750af, 0x47691f and 0x47698c, read at 0x477e33 and 0x478483, and no non-zero writer was found by a byte scan of tp.exe's code) and that sprite's position, size and scale, to build the sprite pick for objects; the object half of the ray pick (RIDES-021)"),
		("UI-031", "exactly Ctrl at the placing click keeps the build tool armed (0x5253b8) and at the last click of a ride's queue re-arms it, the tool's angle returns to 0 when it is left (0x52f3b6); the coaster and water-track tools, whose original sub-modes are not traced, end the build tool whatever the modifier; the Ctrl word 0xC at 0x5259e2/0x5259f4 is Ctrl alone (the modifier builder 0x46b420: Shift 3, Ctrl 0xC, Alt 0x30) and a placement that 0x52fab0 reports as entrance-bearing (the sub-record flag +0x40) takes the tail 0x5259ae: the queue re-evaluation 0x4de1f0, the words 0x763ac0 and 0x763ac4 back to 0x80, then the map cell record +0x29c (the cell's type word, +8 of the 0x44-byte record at +0x294) of the queue's start cell that 0x52a050 gave decides at 0x5259cf: type 1 (a path cell) ends the tool through 0x52f200(0, 0) whatever the modifier, and then, as for any other start cell, exactly Ctrl keeps the angle (0x525a06) and any other word runs 0x52f1b0(0, 0), which resets it, the mode having been set to the queue tool 3 by 0x52f580 before; the coaster sub-mode (0x52faf0 = 3) takes the same tail and skips only the kart and water station line, so the tail itself enters the queue tool for a coaster as well, and the coaster's track tool (mode 0x15, 0x4474d0) is not entered anywhere in 0x524960; which OpenTPW placements end at 0x5259cf is not mapped; Level.PlaceObject owns purchase/guest linkage and its removal handler owns scrap credits", "where the original's coaster placement enters its track tool, if it does (OpenTPW enters it at the placement; the callers of the tool builder 0x46c580 and of 0x4988c0 are not traced), and which of OpenTPW's placements have a path cell as the queue's start"),
		("UI-034", "a fully opaque texture on a transparent (flag 0x2) model slot keys out black with a soft edge: transparent up to channel 6, opaque from 48, alpha ramped and colour un-premultiplied between (only ipan in the lobby f_lobbutbg panel); the texture state routine 0x567c10 sets an alpha test, an alpha reference and blend factors from the record flag bits (mask 0x556), but that its record flag 0x2 is the slot's flag 0x2 is not shown", "the original's render state for flagged texture slots (whether the record flag in 0x567c10 is the slot flag, and the colour-key handling of an opaque texture)"),
		("UI-037", "option bar label colour (16,16,48), no drop shadow; the original's options labels (0x4a43b0) and slider labels (0x4a4490) are text controls given the colour (0,0,0,255) (0x4a441e, 0x4a44fe) and font slot 6 ([0x7537b4]) and drawn once without a shadow (0x48f830); the control's colour (0,0,0,255) is stored as ARGB at control +0x78 (0x48fd07-0x48fd91), which is the colour at +0x24 of its sprite record, and the sprite draw 0x58a010 reads it as the diffuse colour of the text quads (0x58a019); how that diffuse colour combines with the grey, alpha-0 glyph bitmap on screen (texture-stage and blend state) is not read, so the capture's near-black is kept", "the blend and texture-stage state of the text quads (see UI-007): whether black diffuse over white-coverage texels gives (0,0,0) or the capture's (16,16,48)"),
		("UI-041", "Load Park takes no game type from the loaded park: the original derives GameType from flag bits 0x2000000/0x1000000 of 0x7a1a8c (0x550ca0), set by a front-end toggle (0x4bbf63), and the Mac saves none with a park", "whether a park file of the PC build can carry the game type (not traced)"),
		("UI-042", "the camera button's slide-out panel (table 0x751720) slides in and out as the arm drawer 0x4a14f0 does (ten 20 ms steps, cat_ui 0x1C and 0xC2, help 0x131), but its slide ends at the table rectangle where the original's positions come from the HUD arm window ([0x7cb2b8], its child 0x21 found at 0x4a1b35) and the arm: the arithmetic of 0x4a1613-0x4a1650 starts the panel at the arm's left less the HUD window rectangle's width and 50, centres it on the arm and puts its top 50 units above the HUD window's top (read from the instructions, medium confidence; the end position is not resolved); the camcorder button arms the C-key walk ([EXT:camcorder-first-person]) where the original's button 99 enters the camcorder at once (0x498ad0 → 0x481a10), and the walk's movement and look controls are not traced (the original's eye is terrain + 5 units, 0x42b1c0); the postcard window (table 0x7540d8) keeps its photo frame empty and its preview and address book buttons disabled (the 640×240 camcorder photo 0x4a9280, the preview redraw 0x4a84c0 and the address book 0x4a8140 are not ported); the original has no view-cycle button, so OpenTPW has none (0x751720 holds only the two buttons; no window control changes the zoom or yaw, and the locate jumps 0x42aab0 pass null zoom and yaw)", "the HUD window's rectangle; the walk's key bindings (action table 0x787c14) and the time unit of its turn step; the photo, its preview and the address book"),
		("UI-046", "the gauge bars (buy, ride, shop and sideshow windows) take the original's values and shape: the integer (value << 10) / 100 of a 0..1024 range (0x4abb00, 0x4ade40), a bar of the control's cell less 10 units top and bottom (0x485e30) that shows the art cut off at the value with the rest of the cell the track (0x478400: ridestatbar.wct's top 16 texel rows the bar, its bottom 16 the track); the colours of the bar and the track are read off the 720p video (a 70 % bar runs red, orange, yellow to lime green) because the decoded art's colours (now that the chroma decode is fixed, a red-orange start running to green) were not matched against the video", "the gauge sprite's colours as the original draws them (the draw of 0x477ff0, which would let the sprite replace the video-read ramp)"),
		("UI-047", "which OpenTPW tool state corresponds to the mode-object types that show control 48: type 3 (the tool-mode object, vtable 0x6fe9e0) wraps every build tool, so the held blueprint's price, the path or queue line's cost so far and the coaster track segment under the cursor show it; type 8 is the coaster panel's mode object (vtable 0x6feaa0, built by 0x46cfc0 when a panel button is pressed, 0x497bc0), which shows it only while bit 0 of 0x79c658 is set (0x447990; set at 0x441a5d), a placement-in-progress state OpenTPW does not track for the coaster tool (the bit is set at 0x441a5d when (flags & 0x3f) is 0 and cleared by the second action, 0x441a00; medium confidence), so OpenTPW shows the coaster cost in every sub-mode; no mode-object class returns type 4 (the classes 0x6fe980-0x6fead0 return 7, 3, 1, 5, 6, 8 and 9; 5 and 6 are the staff place and carry tools), and the staff and patrol tools show nothing", "which OpenTPW coaster tool state corresponds to the placement-in-progress bit of 0x79c658, and the class that returns type 4"),
		("UI-050", "the buy list's third column draws a tick box per row, ticked when the park owns at least one of the item; the box and the tick are drawn with rectangles and strokes in the video's colours, not the original's art (i_boxtick.MD2 holds only the empty box); the original's row cell 0x4ad340 sets the model i_boxtick (0x755144) on a child, and the owned state is 1 for an owned count of at least one (0x4d3d80, populate 0x4aaf70), else 2 for the first three items of a category (0x4caa70), else 0 (stored through 0x66403b), but what each state draws is not read", "the handler that turns the cell state into a frame (the message 0xc00 path) and the frames of i_boxtick"),
		("UI-051", "the ticket counter is the park's available tickets, where the original shows the player's earned tickets less the spent count (0x5af5d0, called by the HUD's counter handler 0x4a0fb0 at 0x4a10cd: the four global flags counted once, the six local bytes of every park and the two secret flags, so a global ticket that moves between parks (0x5af940) never changes it, and a park here counts the global tickets in its own set, a moved one in both parks' sets), because OpenTPW's park keeps its own spent count and never moves the player ledger's, where the original's purchase check 0x4d4ad0 calls 0x5af740, which adds the cost to the player's spent count (+0x1c) when 0x5b1930 passes; the key counter is the ledger's (0x5af680, matched)", "routing the park's ticket purchases into the player ledger (a design decision: the ledger is optional and absent in the sandbox and Instant Action)"),
		("UI-060", "finance graph: the eight series' colours (the records of 0x499f30), their order and the selection masks (0x49a2e0: the bank balance and the park value clear the six cash-flow series, a cash-flow series clears the pair), the ten-division scale from min(0, lowest sample) to max(0, highest) (0x47fb30) and the default series (the bank balance, word 0x751fa0 = 1) follow tp.exe; the line style (two-unit strokes, grid lines, point marks) and the one-unit scale OpenTPW gives a flat range are OpenTPW's", "the original's graph drawer 0x47fe90 (stroke style, grid, point marks) and its empty or flat range"),
		("UI-064", "the research workload knob is the original's slider: values 1023 (top) to 0 (bottom), a limit of ((100 - c) / 3 + c) x 1024 / (MaxResearchersInPark x the grade-4 ResearchAbility) from the researchers' summed ability c, a workload of 70 + 30 x value / limit and the ball's travel (0x4a96b0, 0x4aac80, 0x66b088); a drag that starts on the ball moves it by the pointer's movement, clamped to the track, as 0x66b771 does; the knob's child 0xd2d12 (set to the limit) and 0xd2d11 (state (2 x step) / 7) are not drawn; the slider's ball proc 0x66bb9b moves the ball by the pointer's offset from the press point (stored per button at 0x10005 in 0xfaa59a/0xfaa59c) from the rectangle saved at the press or release (0x65cf3d), clamped to the track by 0x66b771, then reads the value back with 0x66af19, and a press in the track outside the ball puts the ball's centre under the pointer where the slider class pages by its step (0x66b8aa, 0x66b088 with the page word +0x148, whose value is not found)", "what 0xd2d12 and 0xd2d11 draw, the page step of a press in the track, and whether the saved rectangle is the press-time ball"),
		("UI-081", "applicant details: the skill gauge is a type-9 gauge set to the candidate's grade byte (+8, written by 0x507600 as AvgGradeOf* + R % 3 - 1 stored as 4 when above 4, OpenTPW's Grade) x 1024 / 5 (0x49b8e2) of its 0..1024 range (0x66d885 clamps), so a grade-0 candidate's value is 0; OpenTPW fills (Grade + 1) / 5 because the video's cheapest ($60) candidate shows about a fifth (12:00); the gauge models crop their art to value × 100 / 1024 per cent (UI-046), so a byte of 0 draws an empty bar and the fifth is not explained by the drawing", "which byte the video's cheapest candidate holds (the writer 0x507600 stores AvgGradeOf* + R % 3 - 1 as a byte, a wrapped 0xff becoming 4)"),
		("UI-082", "the hire window's figure is drawn one sprite pixel to 3.2 canvas units (640 pixels across the 2048-unit canvas), where the original sets its register 8 to 8.0 (0x004755D0, the scale 0x00542010 copies to the draw record +0x2C, default 1.0; the record slot 8 is +0xA4, the X scale, +0xA8 the second scale, both default 1.0); how the screen-sprite path (flag 0x40000, list 0x0087692C, count 0x875864) turns that scale into pixels is not traced: the list and its snapshot 0x876424 have no reader by absolute address, so the code that consumes them is not found; the figure also shows for an employee selected in the employed view, where 0x49BA00 reads only the applicant pool (0x507BD0, 32 entries of 0x14 bytes)", "the engine's screen-sprite quad size, or a capture of the hire window and of the employed view"),
